   445→}
   446→
   447→export interface Pipeline {
   448→  id: string;
   449→  description?: string;
   450→  processors: PipelineProcessor[];
   451→}
   452→
   453→export interface PipelineProcessor {
   454→  [type: string]: {
   455→    field?: string;
