   461→    target_field?: string;
   462→    ignore_failure?: boolean;
   463→    [key: string]: unknown;
   464→  };
   465→}
   466→
   467→export interface Scheduler {
   468→  id: string;
   469→  name: string;
   470→  cron: string;
   471→  collectionId: string;
   472→  collectionName?: string;
   473→  enabled: boolean;
