// ========================================
// User & Auth Types
// ========================================

export interface User {
  id?: string;
  username: string;
  email: string;
  role: string;
  roles: string[];
}

export interface Role {
  id: string;
  name: string;
  analysis: boolean;
  index: boolean;
  search: boolean;
  manage: boolean;
  inUse: boolean;
}

// ========================================
// Cluster Types
// ========================================

export interface Cluster {
  id: string;
  name: string;
  host: string;
  port: number;
  scheme: 'http' | 'https';
  username?: string;
  password?: string;
  kibana?: string;
  theme: ClusterTheme;
  nodeCount: number;
  indexCount: number;
  shardCount: number;
  docCount?: number;
  storeSize: string;
  status: HealthStatus;
  dictCluster?: string;
  serverCheck?: boolean;
}

export type ClusterTheme = 'dark' | 'light' | 'blue' | 'green' | 'indigo' | 'teal';
export type HealthStatus = 'green' | 'yellow' | 'red';

export interface ClusterHealth {
  cluster_name: string;
  status: HealthStatus;
  timed_out: boolean;
  number_of_nodes: number;
  number_of_data_nodes: number;
  active_primary_shards: number;
  active_shards: number;
  relocating_shards: number;
  initializing_shards: number;
  unassigned_shards: number;
  delayed_unassigned_shards: number;
  number_of_pending_tasks: number;
  number_of_in_flight_fetch: number;
  task_max_waiting_in_queue_millis: number;
  active_shards_percent_as_number: number;
}

export interface ClusterStats {
  nodes: {
    count: {
      total: number;
      data: number;
      master: number;
      ingest: number;
    };
  };
  indices: {
    count: number;
    shards: {
      total: number;
      primaries: number;
    };
    docs: {
      count: number;
      deleted: number;
    };
    store: {
      size_in_bytes: number;
    };
  };
}

export interface ClusterNode {
  id: string;
  name: string;
  ip: string;
  roles: string[];
  master: boolean;
  heap: {
    percent: number;
    max: string;
    used: string;
  };
  cpu: number;
  load: string;
  diskUsed: string;
  diskTotal: string;
  diskPercent: number;
}

export interface ClusterSettings {
  persistent: Record<string, unknown>;
  transient: Record<string, unknown>;
  defaults: Record<string, unknown>;
}

// ========================================
// Index Types
// ========================================

export interface Index {
  health: HealthStatus;
  status: 'open' | 'close';
  index: string;
  uuid: string;
  pri: string;
  rep: string;
  docsCount: string;
  docsDeleted: string;
  storeSize: string;
  priStoreSize: string;
  frozen?: boolean;
  aliases?: string[];
}

export interface IndexDetail {
  index: string;
  health: HealthStatus;
  status: 'open' | 'close';
  frozen: boolean;
  pri: number;
  rep: number;
  docsCount: number;
  docsDeleted: number;
  storeSize: string;
  priStoreSize: string;
  aliases: string[];
  mappings: IndexMappings;
  settings: IndexSettings;
}

export interface IndexMappings {
  properties: Record<string, MappingProperty>;
}

export interface MappingProperty {
  type: string;
  index?: boolean;
  analyzer?: string;
  search_analyzer?: string;
  copy_to?: string | string[];
  ignore_above?: number;
  null_value?: string;
  doc_values?: boolean;
  similarity?: string;
  term_vector?: string;
  fields?: Record<string, MappingProperty>;
  properties?: Record<string, MappingProperty>;
}

export interface IndexSettings {
  index: {
    number_of_shards: string;
    number_of_replicas: string;
    refresh_interval: string;
    provided_name?: string;
    creation_date?: string;
    uuid?: string;
    version?: {
      created: string;
    };
    [key: string]: unknown;
  };
}

export interface IndexStats {
  docs: {
    count: number;
    deleted: number;
  };
  store: {
    size_in_bytes: number;
  };
  indexing: {
    index_total: number;
    index_time_in_millis: number;
    index_current: number;
    index_failed: number;
  };
  search: {
    query_total: number;
    query_time_in_millis: number;
    query_current: number;
    fetch_total: number;
    fetch_time_in_millis: number;
    fetch_current: number;
  };
  [key: string]: unknown;
}

export interface IndexTemplate {
  name: string;
  index_patterns: string[];
  mappings?: IndexMappings;
  settings?: Record<string, unknown>;
  order?: number;
  version?: number;
}

// ========================================
// Collection Types
// ========================================

export interface Collection {
  id: string;
  name: string;
  baseId: string;
  description?: string;
  indexA: string;
  indexB: string;
  selectedIndex: string;
  aliasA?: string;
  aliasB?: string;
  jdbcId?: string;
  jdbcInfo?: string;
  sourceName: string;
  sourceType: CollectionSourceType;
  sourceConfig?: string;
  shard: number;
  replica: number;
  refreshInterval: string;
  docCount: number;
  size: string;
  autoRun: boolean;
  schedule?: string;
  createdAt?: string;
  updatedAt?: string;
}

export type CollectionSourceType =
  | 'multipleDumpFile'
  | 'ndjson'
  | 'csv'
  | 'file'
  | 'procedure'
  | 'database'
  | 'reindex';

export interface CollectionHistory {
  id: string;
  collectionId: string;
  time: string;
  indexA: string;
  indexB: string;
  status: 'SUCCESS' | 'FAILED' | 'RUNNING' | 'CANCELLED';
  type: 'FULL_INDEX' | 'EXPOSE' | 'AUTO';
  message?: string;
  elapsed?: number;
  docCount?: number;
}

export interface RunningIndex {
  collectionId: string;
  collectionName: string;
  index: string;
  progress: number;
  estimatedTime: number;
  elapsedTime: number;
  processedDocs: number;
  totalDocs: number;
  startTime: string;
  currentStep: 'FULL_INDEX' | 'EXPOSE';
  nextStep?: string;
}

export interface WarningIndex {
  index: string;
  health: 'yellow' | 'red';
  message: string;
}

export interface IndexResult {
  index: string;
  alias?: string;
  status: 'SUCCESS' | 'FAILED';
  lastSuccess?: string;
  elapsed?: number;
  docCount: number;
  size: string;
  endTime: string;
}

// ========================================
// Analysis Types
// ========================================

// 8개 사전 타입 정의
export type DictionaryType =
  | 'STOP'        // SET: 불용어
  | 'USER'        // SET: 사용자 정의 단어
  | 'ENGLISH'     // SET: 영문 단어
  | 'UNIT'        // SET: 단위
  | 'SYNONYM'     // SYNONYM: 동의어 (양방향/단방향)
  | 'UNIT_SYNONYM'// SYNONYM: 단위 동의어
  | 'SPACE'       // MAP: 공백 분리
  | 'COMPOUND';   // MAP: 복합어 분해

// 데이터 구조 카테고리
export type DictionaryCategory = 'SET' | 'SYNONYM' | 'MAP';

// 카테고리별 타입 매핑
export const DICTIONARY_CATEGORY_MAP: Record<DictionaryType, DictionaryCategory> = {
  STOP: 'SET',
  USER: 'SET',
  ENGLISH: 'SET',
  UNIT: 'SET',
  SYNONYM: 'SYNONYM',
  UNIT_SYNONYM: 'SYNONYM',
  SPACE: 'MAP',
  COMPOUND: 'MAP',
};

// 사전 타입별 레이블
export const DICTIONARY_TYPE_LABELS: Record<DictionaryType, string> = {
  STOP: '불용어',
  USER: '사용자 단어',
  ENGLISH: '영문 단어',
  UNIT: '단위',
  SYNONYM: '동의어',
  UNIT_SYNONYM: '단위 동의어',
  SPACE: '공백 분리',
  COMPOUND: '복합어',
};

export interface Dictionary {
  id: string;
  type: DictionaryType;
  keyword: string | null;  // null for bidirectional synonym
  value: string;
  createdAt?: string;
  updatedAt?: string;
}

// SYNONYM 전용: 양방향/단방향 구분
export interface SynonymDictionary extends Dictionary {
  type: 'SYNONYM' | 'UNIT_SYNONYM';
  direction: 'bidirectional' | 'unidirectional';
}

export interface DictionarySummaryItem {
  type: DictionaryType;
  name: string;
  count: number;
  modifiedTime?: string;
  appliedCount?: number;
  appliedTime?: string;
  tokenType?: string;
  ignoreCase?: boolean;
  compiled: boolean;
  hasChanges: boolean;
}

export interface DictionaryCompileStatus {
  type: DictionaryType;
  status: 'COMPILED' | 'PENDING' | 'ERROR';
  lastCompiled?: string;
  message?: string;
}

export interface AnalysisResult {
  tokens: AnalysisToken[];
}

export interface AnalysisToken {
  token: string;
  start_offset: number;
  end_offset: number;
  type: string;
  position: number;
}

export interface DetailAnalysisResult {
  index: string;
  field: string;
  content: string;
  analyzed: string;
}

export interface SavedQuery {
  id: string;
  name: string;
  index: string;
  query: string;
  createdAt: string;
}

// ========================================
// Search Types
// ========================================

export interface SearchTemplate {
  id: string;
  name: string;
  indices: string;
  query: string;
  title: string;
  clickUrl: string;
  thumbnails: string;
  order: number;
  fields: Array<{ label: string; value: string }>;
  aggs: Array<{ label: string; value: string }>;
}

export interface ReferenceUIConfig {
  autocompleteUrl?: string;
  templates: SearchTemplate[];
}

// ========================================
// Management Types
// ========================================

export interface JDBCSource {
  id: string;
  name: string;
  driver: string;
  driverClass: string;
  url: string;
  host: string;
  port: string;
  database: string;
  user: string;
  password: string;
  jdbcParams?: string;
}

export interface Pipeline {
  id: string;
  description?: string;
  processors: PipelineProcessor[];
}

export interface PipelineProcessor {
  [type: string]: {
    field?: string;
    value?: string;
    pattern?: string;
    replacement?: string;
    separator?: string;
    source?: string;
    target_field?: string;
    ignore_failure?: boolean;
    [key: string]: unknown;
  };
}

export interface Scheduler {
  id: string;
  name: string;
  cron: string;
  collectionId: string;
  collectionName?: string;
  enabled: boolean;
  status: 'RUNNING' | 'STOPPED' | 'IDLE';
  lastRun?: string;
  nextRun?: string;
}

// ========================================
// Shard Types
// ========================================

export interface Shard {
  index: string;
  shard: string;
  prirep: 'p' | 'r';
  state: 'STARTED' | 'RELOCATING' | 'INITIALIZING' | 'UNASSIGNED';
  docs?: string;
  store?: string;
  ip?: string;
  node?: string;
}

// ========================================
// API Response Types
// ========================================

export interface ApiResponse<T> {
  success: boolean;
  data?: T;
  error?: string;
  message?: string;
}

export interface PaginatedResponse<T> {
  items: T[];
  total: number;
  page: number;
  pageSize: number;
  totalPages: number;
}

// ========================================
// UI State Types
// ========================================

export interface TableColumn<T> {
  key: keyof T | string;
  label: string;
  sortable?: boolean;
  width?: string;
  render?: (value: unknown, item: T) => React.ReactNode;
}

export interface SortConfig {
  key: string;
  direction: 'asc' | 'desc';
}

export interface FilterConfig {
  field: string;
  value: string;
  operator: 'eq' | 'contains' | 'gt' | 'lt';
}

// ========================================
// Re-export Dictionary Backend Types
// ========================================

export type {
  DictionaryWithId,
  CompileResult,
  CreateDictionaryRequest,
  UpdateDictionaryRequest,
  BackendPagedResponse,
  BackendCursorResponse,
} from './dictionary';

export { DICTIONARY_API } from './dictionary';

// ========================================
// Cursor-based Pagination Types
// ========================================

export interface CursorPaginatedResponse<T> {
  items: T[];
  total: number;
  nextCursor: string | null;
  hasNext: boolean;
}

