'use client';

import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import apiClient from '@/lib/api/client';
import { mapCursorDictionaryResponse } from '@/lib/api/dictionary-mapper';
import type {
  Dictionary,
  DictionaryType,
  CursorPaginatedResponse,
  DictionaryWithId,
  BackendCursorResponse,
} from '@/types';

// ========================================
// Query Keys
// ========================================

export const analysisKeys = {
  all: ['analysis'] as const,
  dictionaries: () => [...analysisKeys.all, 'dictionaries'] as const,
  dictionaryList: (type: DictionaryType, cursor?: string | null, search?: string) =>
    [...analysisKeys.dictionaries(), type, { cursor, search }] as const,
};

// ========================================
// Dictionary List Hooks (Cursor-based)
// ========================================

interface DictionaryListParams {
  type: DictionaryType;
  cursor?: string | null;
  pageSize?: number;
  search?: string;
  searchField?: 'all' | 'keyword' | 'value';
  wordMatch?: boolean;
}

export function useDictionaries(params: DictionaryListParams) {
  const { type, cursor = null, pageSize = 20, search, wordMatch = false } = params;

  return useQuery({
    queryKey: analysisKeys.dictionaryList(type, cursor, search),
    queryFn: async (): Promise<CursorPaginatedResponse<Dictionary>> => {
      // If search is provided, use search endpoint (returns array)
      if (search && search.trim()) {
        const response = await apiClient.get<DictionaryWithId[]>(
          `/api/v1/dictionary/${type}/search`,
          {
            params: {
              word: search,
              isMatch: wordMatch,
            },
          }
        );
        // Convert search results to cursor response format
        const items = response.data;
        return {
          items: items.map((item) => ({
            id: item.id,
            type: item.dictionary.type,
            keyword: item.dictionary.keyword,
            value: item.dictionary.value ?? '',
            createdAt: item.dictionary.createdTime,
            updatedAt: item.dictionary.updatedTime,
          })),
          total: items.length,
          nextCursor: null,
          hasNext: false,
        };
      }

      // Cursor-based list endpoint - avoids ES from+size 10,000 limit
      const response = await apiClient.get<BackendCursorResponse>(
        `/api/v1/dictionary/${type}/cursor`,
        {
          params: {
            size: pageSize,
            ...(cursor && { cursor }),
          },
        }
      );
      return mapCursorDictionaryResponse(response.data);
    },
    staleTime: 30000, // 30 seconds
  });
}

// ========================================
// Dictionary CRUD Hooks
// ========================================

interface CreateDictionaryParams {
  type: DictionaryType;
  keyword?: string | null;
  value?: string | null;
}

export function useCreateDictionary() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (params: CreateDictionaryParams) => {
      const response = await apiClient.post(
        '/api/v1/dictionary',
        {
          keyword: params.keyword,
          type: params.type,
          value: params.value,
        }
      );
      return response.data;
    },
    onSuccess: (_, variables) => {
      queryClient.invalidateQueries({
        queryKey: analysisKeys.dictionaryList(variables.type),
      });
    },
  });
}

interface UpdateDictionaryParams {
  type: DictionaryType;
  id: string;
  keyword?: string | null;
  value?: string | null;
}

export function useUpdateDictionary() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (params: UpdateDictionaryParams) => {
      const response = await apiClient.put(
        `/api/v1/dictionary/${params.id}`,
        {
          keyword: params.keyword ?? '',
          type: params.type,
          value: params.value,
        }
      );
      return response.data;
    },
    onSuccess: (_, variables) => {
      queryClient.invalidateQueries({
        queryKey: analysisKeys.dictionaryList(variables.type),
      });
    },
  });
}

interface DeleteDictionaryParams {
  type: DictionaryType;
  ids: string[];
}

export function useDeleteDictionary() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (params: DeleteDictionaryParams) => {
      // Backend only supports single delete, so we delete in parallel
      await Promise.all(
        params.ids.map(id =>
          apiClient.delete(`/api/v1/dictionary/${id}`)
        )
      );
    },
    onSuccess: (_, variables) => {
      queryClient.invalidateQueries({
        queryKey: analysisKeys.dictionaryList(variables.type),
      });
    },
  });
}

import type { Dictionary, DictionaryWithId, PaginatedResponse, BackendPagedResponse, BackendCursorResponse, CursorPaginatedResponse } from '@/types';

/**
 * Transform backend DictionaryWithId response to frontend Dictionary model
 */
export function mapDictionaryResponse(data: DictionaryWithId): Dictionary {
  return {
    id: data.id,
    type: data.dictionary.type,
    keyword: data.dictionary.keyword,
    value: data.dictionary.value ?? '',
    createdAt: data.dictionary.createdTime,
    updatedAt: data.dictionary.updatedTime,
  };
}

/**
 * Transform backend PagedResponse to frontend PaginatedResponse
 * Uses the total count from backend for accurate pagination
 */
export function mapPagedDictionaryResponse(
  data: BackendPagedResponse,
  requestedPage: number,
  pageSize: number
): PaginatedResponse<Dictionary> {
  return {
    items: data.items.map(mapDictionaryResponse),
    total: data.total,
    page: requestedPage,
    pageSize,
    totalPages: data.totalPages,
  };
}

/**
 * Transform array of backend responses to paginated frontend response
 * Used for search results that return arrays without pagination metadata
 */
export function mapDictionaryListResponse(
  data: DictionaryWithId[],
  page: number,
  pageSize: number
): PaginatedResponse<Dictionary> {
  return {
    items: data.map(mapDictionaryResponse),
    total: data.length,
    page,
    pageSize,
    totalPages: Math.max(1, Math.ceil(data.length / pageSize)),
  };
}

/**
 * Transform backend CursorPagedResponse to frontend CursorPaginatedResponse
 * Used for cursor-based pagination that avoids ES from+size limit
 */
export function mapCursorDictionaryResponse(
  data: BackendCursorResponse
): CursorPaginatedResponse<Dictionary> {
  return {
    items: data.items.map(mapDictionaryResponse),
    total: data.total,
    nextCursor: data.nextCursor,
    hasNext: data.hasNext,
  };
}

