   443→      </div>
   444→
   445→      {/* Cursor-based Pagination */}
   446→      <div className="flex items-center justify-between">
   447→        <div className="text-sm text-muted-foreground">
   448→          총 {total.toLocaleString()}건
   449→          {!activeSearch && ` · 페이지 ${currentPage}`}
   450→        </div>
