import type { DictionaryType } from './index';

// ========================================
// Backend Response DTOs
// ========================================

/**
 * Backend response for a single dictionary entry
 * Matches Spring Boot DictionaryWithId response
 */
export interface DictionaryWithId {
  id: string;
  dictionary: {
    keyword: string | null;
    type: DictionaryType;
    value: string | null;
    createdTime: string; // ISO 8601 timestamp
    updatedTime: string; // ISO 8601 timestamp
  };
}

/**
 * Backend response for dictionary compilation
 * Matches Spring Boot CompileResult response
 */
export interface CompileResult {
  type: DictionaryType;
  count: number;
  filePath: string;
  fileSize: number;
}

// ========================================
// Backend Request DTOs
// ========================================

/**
 * Request body for creating a new dictionary entry
 * POST /api/v1/dictionary
 */
export interface CreateDictionaryRequest {
  keyword?: string | null;
  type: DictionaryType;
  value?: string | null;
}

/**
 * Request body for updating a dictionary entry
 * PUT /api/v1/dictionary/{id}
 */
export interface UpdateDictionaryRequest {
  keyword: string;
  type: DictionaryType;
  value?: string | null;
}

// ========================================
// API Path Constants
// ========================================

export const DICTIONARY_API = {
  BASE: '/api/v1/dictionary',
  list: (type: DictionaryType) => `/api/v1/dictionary/${type}`,
  search: (type: DictionaryType) => `/api/v1/dictionary/${type}/search`,
  create: () => '/api/v1/dictionary',
  update: (id: string) => `/api/v1/dictionary/${id}`,
  delete: (id: string) => `/api/v1/dictionary/${id}`,
  compile: () => '/api/v1/dictionary/compile',
  compileType: (type: DictionaryType) => `/api/v1/dictionary/compile/${type}`,
} as const;

/**
 * Backend paginated response format
 * Matches Spring Boot PagedResponse<DictionaryWithId>
 */
export interface BackendPagedResponse {
  items: DictionaryWithId[];
  total: number;
  page: number;
  size: number;
  totalPages: number;
}

/**
 * Backend cursor-based paginated response format
 * Matches Spring Boot CursorPagedResponse<DictionaryWithId>
 */
export interface BackendCursorResponse {
  items: DictionaryWithId[];
  total: number;
  nextCursor: string | null;
  hasNext: boolean;
}

