### 5. How to Add New API Hooks

For the three new endpoints (`/last-modified`, `/count`, `/compile`), add the following to `use-analysis.ts`:

#### Hook 1: Dictionary Count by Type
```typescript
export const analysisKeys = {
  // ... existing keys
  dictionaryStats: () => [...analysisKeys.all, 'stats'] as const,
  dictionaryCount: () => [...analysisKeys.dictionaryStats(), 'count'] as const,
  dictionaryLastModified: () => [...analysisKeys.dictionaryStats(), 'lastModified'] as const,
  dictionaryCompileStatus: () => [...analysisKeys.dictionaryStats(), 'compile'] as const,
};

// Hook: Get count for all dictionary types
export function useDictionaryCounts() {
  return useQuery({
    queryKey: analysisKeys.dictionaryCount(),
    queryFn: async (): Promise<Record<DictionaryType, number>> => {
      const response = await apiClient.get(
        '/api/v1/dictionary/count'
      );
      return response.data;
    },
    staleTime: 60000, // 1 minute
  });
}
```

#### Hook 2: Last Modified Timestamp
```typescript
export function useDictionaryLastModified() {
  return useQuery({
    queryKey: analysisKeys.dictionaryLastModified(),
    queryFn: async (): Promise<Record<DictionaryType, string>> => {
      const response = await apiClient.get(
        '/api/v1/dictionary/last-modified'
      );
      return response.data;
    },
    staleTime: 60000, // 1 minute
  });
}
```

#### Hook 3: Compile Status
```typescript
// Compile all dictionaries
export function useCompileDictionaries() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async () => {
      const response = await apiClient.post(
        '/api/v1/dictionary/compile'
      );
      return response.data;
    },
    onSuccess: () => {
      // Invalidate related queries
      queryClient.invalidateQueries({
        queryKey: analysisKeys.dictionaryStats(),
      });
    },
  });
}

// Compile specific dictionary type
export function useCompileDictionaryType() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (type: DictionaryType) => {
      const response = await apiClient.post(
        `/api/v1/dictionary/compile/${type}`
      );
      return response.data;
    },
    onSuccess: (_, type) => {
      queryClient.invalidateQueries({
        queryKey: analysisKeys.dictionaryStats(),
      });
    },
  });
}
```

